    DocumentState state;state.base=std::make_shared<Image>(std::move(image));for(int i=0;i<48;++i){Annotation a;a.tool=i%4==0?Tool::Text:i%4==1?Tool::Rectangle:i%4==2?Tool::Highlight:Tool::Arrow;const int x=100+i%8*420,y=100+i/8*260;a.rect={x,y,x+260,y+140};a.points={{x,y},{x+260,y+140}};a.text=L"Performance 4K 測試";a.fontSize=28;state.objects.push_back(a);}Annotation effect;effect.tool=Tool::Blur;effect.rect={500,400,1500,1000};effect.width=4;state.objects.push_back(effect);effect.tool=Tool::Mosaic;effect.rect={1800,800,2500,1400};state.objects.push_back(effect);return state;
