    static EditorFrame::WorkResult Take(EditorFrame* p){const auto deadline=Clock::now()+std::chrono::seconds(12);while(Clock::now()<deadline){if(auto result=p->job_.Take())return std::move(*result);Sleep(1);}throw std::runtime_error("Private copy packet timeout");}
