        for(int i=0;i<6;++i){page->draft_.rect={2800+i*10,1600,3100+i*10,1800};const auto start=Clock::now();page->Preview();page->RequestRender();const auto submit=Ms(start);Drain(page);const auto elapsed=Ms(start);if(i){submits.push_back(submit);frames.push_back(elapsed);}auto expected=source;expected.objects.push_back(page->draft_);core::Image rendered;const auto oracleStart=Clock::now();const bool exact=services::RenderDocument(expected,rendered,error);const auto oracleElapsed=Ms(oracleStart);if(i)oracles.push_back(oracleElapsed);check(exact&&page->image_.pixels==rendered.pixels,"every drawing preview matches complete order-dependent rendering byte-for-byte");}
